import { projects as raw } from './portfolioData.js';
import devices from './devicePreviews.json';

export type Project = (typeof raw)[number] & {
  githubLink?: string;
  liveLinkLabel?: string;
  previewImageScrollbarWidth?: number;
};

export const projects = raw as Project[];

/** Responsive WebP sources generated by scripts/optimize-previews.mjs */
export const previewSources = (p: Project) => {
  const base = p.previewImage.replace(/\.png$/, '');
  const { width, height } = p.previewImageDimensions;
  // Hide only the browser scrollbar captured at the screenshot's right edge.
  const contentWidth = width - (p.previewImageScrollbarWidth ?? 0);
  return {
    srcset: `${base}-720.webp 720w, ${base}-1440.webp 1440w`,
    src: `${base}-720.webp`,
    fallback: p.previewImage,
    width,
    height,
    style: `width: ${width / contentWidth * 100}%; max-width: none;`,
  };
};

export const primaryTag = (p: Project) => p.tags[0];

/** A short category label for the index list. */
export const kindOf = (p: Project) => {
  const t = p.tags.join(' ').toLowerCase();
  if (/3d/.test(t)) return '3D experience';
  if (/stripe|matching|crm|dashboard|supabase/.test(t) && /react|next/.test(t)) return 'Web app';
  if (/mcp|python/.test(t)) return 'Open source';
  if (/bot|automation/.test(t)) return 'Automation';
  return 'Website';
};

/**
 * MacBook + phone screenshots generated by scripts/optimize-previews.mjs from
 * public/project-previews/devices/<slug>-{desktop,mobile}.png
 * (desktop: 1440x810 viewport at 2x, phone: 390x764 viewport at 3x).
 */
export const deviceSources = (p: Project) => {
  const base = `/project-previews/devices/${p.slug}`;
  const meta = (devices as Record<string, { statusBg: string; statusInk: string }>)[p.slug];
  return {
    desktop: {
      srcset: `${base}-desktop-960.webp 960w, ${base}-desktop-1920.webp 1920w`,
      src: `${base}-desktop-1920.webp`,
      width: 1920,
      height: 1080,
    },
    // Phone shot is missing only where the live content could not be rendered faithfully.
    mobile: meta && {
      srcset: `${base}-mobile-480.webp 480w, ${base}-mobile-960.webp 960w`,
      src: `${base}-mobile-960.webp`,
      width: 960,
      height: 1880,
      statusBg: meta.statusBg,
      statusInk: meta.statusInk,
    },
  };
};
